from pathlib import Path
R=Path('RustySNES')
def edit(path, reps):
    p=R/path; s=p.read_text(encoding='utf-8')
    for old,new in reps:
        if old not in s: raise SystemExit(f'missing pattern in {path}: {old[:80]!r}')
        s=s.replace(old,new,1)
    p.write_text(s,encoding='utf-8')

