(R/'crates/rustysnes-frontend/src/sprite_studio.rs').write_text(r'''//! Visible SNES OBJ capture/export for the HD Sprite Studio.
#[cfg(not(target_arch = "wasm32"))]
pub fn capture_visible_figures(fb:&[u8], tags:&[rustysnes_core::ppu::hdtag::TileTag], dims:(u32,u32), title:Option<&str>) -> Result<(usize,std::path::PathBuf),String> {
 let (w,h)=dims; let n=w as usize*h as usize; if w==0||h==0||fb.len()<n*4||tags.len()<n{return Err("invalid frame/tag buffer".into())}
 let obj=|i:usize| tags[i].hash!=0&&tags[i].class==1&&fb[i*4+3]!=0; let mut seen=vec![false;n]; let mut boxes=Vec::new();
 for st in 0..n { if seen[st]||!obj(st){continue} let mut q=vec![st];seen[st]=true;let(mut x0,mut y0,mut x1,mut y1)=(w,h,0,0);let mut cnt=0;
  while let Some(i)=q.pop(){let x=(i%w as usize)as u32;let y=(i/w as usize)as u32;x0=x0.min(x);y0=y0.min(y);x1=x1.max(x);y1=y1.max(y);cnt+=1;
   for dy in -2..=2{for dx in -2..=2{let nx=x as i32+dx;let ny=y as i32+dy;if nx<0||ny<0||nx>=w as i32||ny>=h as i32{continue}let ni=ny as usize*w as usize+nx as usize;if !seen[ni]&&obj(ni){seen[ni]=true;q.push(ni)}}}}
  if cnt>=4{boxes.push((x0,y0,x1,y1))}
 }
 let base=directories::UserDirs::new().and_then(|d|d.picture_dir().map(std::path::Path::to_path_buf)).unwrap_or_else(||".".into());
 let safe=title.unwrap_or("game").chars().map(|c|if c.is_ascii_alphanumeric()||c=='-'||c=='_'{c}else{'_'}).collect::<String>(); let dir=base.join("RustySNES_Sprite_Studio").join(safe.trim_matches('_'));std::fs::create_dir_all(&dir).map_err(|e|e.to_string())?;
 for (k,(x0,y0,x1,y1)) in boxes.iter().copied().enumerate(){let cw=x1-x0+1;let ch=y1-y0+1;let mut out=vec![0u8;(cw*ch*4)as usize];for y in y0..=y1{for x in x0..=x1{let si=(y*w+x)as usize;if !obj(si){continue}let di=(((y-y0)*cw+x-x0)*4)as usize;out[di..di+4].copy_from_slice(&fb[si*4..si*4+4])}}let bytes=crate::screenshot::encode_png(&out,cw,ch).map_err(|e|e.to_string())?;std::fs::write(dir.join(format!("sprite_{k:04}_{cw}x{ch}.png")),bytes).map_err(|e|e.to_string())?}
 Ok((boxes.len(),dir))
}
''',encoding='utf-8')
